import 'dart:collection';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:toml/toml.dart';
import 'package:yaml/yaml.dart';

typedef _Manifest = Map<String, Object?>;
typedef _Member = ({String name, String path, _Manifest manifest});
typedef _Dependency = ({String name, String scope, Object? spec});
typedef _GitPin = ({String source, String url, String ref, String path});

const _generated =
    '<!-- Generated by `make workspace-graph`; do not edit by hand. -->';
const _pubScopes = {'dependencies': 'runtime', 'dev_dependencies': 'dev'};
const _cargoScopes = {
  'dependencies': 'runtime',
  'dev-dependencies': 'dev',
  'build-dependencies': 'build',
};

void main(List<String> args) {
  final check = args.length == 1 && args.single == '--check';
  if (!check && args.isNotEmpty) {
    stderr.writeln('Usage: fvm dart tools/workspace_graph.dart [--check]');
    exitCode = 64;
    return;
  }

  final root = _pubspec('.');
  final members = [
    _member('.', root),
    for (final path in (root['workspace'] as YamlList).cast<String>())
      _member(path, _pubspec(path)),
  ]..sort((a, b) => a.name.compareTo(b.name));

  final docs = {
    'WORKSPACE.md': _workspace(members),
    'DEPENDENCIES.md': _inventory(members),
  };
  for (final MapEntry(key: path, value: contents) in docs.entries) {
    final file = File(path);
    if (!check) {
      file.writeAsStringSync(contents);
    } else if (!file.existsSync() || file.readAsStringSync() != contents) {
      stderr.writeln('$path is missing or stale.');
      exitCode = 1;
    }
  }
  if (exitCode != 0) {
    stderr.writeln('Run make workspace-graph and commit both generated docs.');
  }
}

_Manifest _map(Object? value) =>
    value == null ? const {} : (value as Map).cast<String, Object?>();

_Manifest _pubspec(String path) =>
    _map(loadYaml(File(p.posix.join(path, 'pubspec.yaml')).readAsStringSync()));

_Member _member(String path, _Manifest manifest) =>
    (name: manifest['name'] as String, path: path, manifest: manifest);

Iterable<_Dependency> _dependencies(
  _Manifest manifest,
  Map<String, String> scopes,
) sync* {
  for (final MapEntry(key: section, value: scope) in scopes.entries) {
    final entries = _map(manifest[section]);
    for (final name in entries.keys.toList()..sort()) {
      yield (name: name, scope: scope, spec: entries[name]);
    }
  }
}

String _workspace(List<_Member> members) {
  final features = members
      .where((m) => m.path.startsWith('features/'))
      .toList();
  final packages = members
      .where((m) => m.path.startsWith('packages/'))
      .toList();
  final out = StringBuffer('''
# Workspace dependency graphs

$_generated

The source of truth is the root `workspace:` list and each member's `pubspec.yaml`. Run `make workspace-graph` from the repository root after `make deps`; CI checks the result with `make workspace-graph-check`.

An arrow points from the consumer to its direct dependency. Each graph shows declarations within one layer, including development dependencies; the table shows feature-to-package dependencies by scope. The root app shell and its legacy source imports are not graphed. See [Architecture](ARCHITECTURE.md#workspace-dependency-rules) for the rules and [Dependencies](DEPENDENCIES.md) for external dependencies.
''');
  _graph(out, 'Features → features', features);
  _graph(out, 'Packages → packages', packages);

  final packageNames = packages.map((m) => m.name).toSet();
  out.write('''

## Features → packages

| Feature | Runtime packages | Dev packages |
| --- | --- | --- |
''');
  for (final feature in features) {
    final deps = _dependencies(
      feature.manifest,
      _pubScopes,
    ).where((dep) => packageNames.contains(dep.name));
    out.writeln(
      '| ${_link(feature)} | ${_list(_byScope(deps, 'runtime').map((d) => _code(d.name)))} '
      '| ${_list(_byScope(deps, 'dev').map((d) => _code(d.name)))} |',
    );
  }
  return out.toString();
}

void _graph(StringBuffer out, String title, List<_Member> members) {
  final names = members.map((m) => m.name).toSet();
  final diagram = StringBuffer('flowchart TD\n');
  var edges = 0;
  for (final member in members) {
    diagram.writeln('  pkg_${member.name}["${member.name}"]');
  }
  for (final member in members) {
    final targets = SplayTreeSet<String>.of(
      _dependencies(
        member.manifest,
        _pubScopes,
      ).map((d) => d.name).where(names.contains),
    );
    for (final target in targets) {
      diagram.writeln('  pkg_${member.name} --> pkg_$target');
      edges++;
    }
  }
  // Mermaid's defaults: https://mermaid.js.org/config/schema-docs/config.html
  if (edges > 500 || diagram.length > 50000) {
    throw StateError('$title exceeds Mermaid size limits; split the diagram.');
  }
  out.write('\n## $title\n\n```mermaid\n$diagram```\n');
}

String _inventory(List<_Member> members) {
  final names = members.map((m) => m.name).toSet();
  final consumers = SplayTreeMap<String, List<String>>();
  final pins = <_GitPin>[];
  final out = StringBuffer('''
# Direct external dependencies

$_generated

Run `make workspace-graph` to regenerate. This inventory lists only direct declarations from the root and workspace `pubspec.yaml` files and the Rust manifests under [rust_bindings](packages/rust_bindings) and [onion](packages/onion). It shows declared constraints, not resolution overrides, resolved versions, transitive dependencies, or licenses. See [Workspace](WORKSPACE.md) for internal Dart dependencies.

## Dart: member → external packages

| Member | Runtime | Dev |
| --- | --- | --- |
''');
  for (final member in members) {
    final deps = _dependencies(
      member.manifest,
      _pubScopes,
    ).where((dep) => !names.contains(dep.name)).toList();
    out.writeln(
      '| ${_link(member)} | ${_list(_byScope(deps, 'runtime').map(_pubCell))} '
      '| ${_list(_byScope(deps, 'dev').map(_pubCell))} |',
    );
    for (final dep in deps) {
      (consumers[dep.name] ??= []).add('${_link(member)} (${dep.scope})');
      if (dep.spec case final Map spec when spec.containsKey('git')) {
        final git = spec['git'];
        final entry = git is String ? {'url': git} : _map(git);
        pins.add((
          source: 'Dart: ${member.name} / ${dep.name} (${dep.scope})',
          url: entry['url'] as String,
          ref: (entry['ref'] as String?) ?? 'not pinned',
          path: (entry['path'] as String?) ?? '',
        ));
      }
    }
  }
  out.write('''

## Dart: external package → members

| External package | Members (scope) |
| --- | --- |
''');
  for (final MapEntry(key: name, value: uses) in consumers.entries) {
    out.writeln('| ${_code(name)} | ${_list(uses)} |');
  }
  _cargo(out, pins);

  out.write('''

## Git sources

Refs are taken from the manifests. Cargo patches are source redirects, not additional direct dependencies.

| Declaration | Repository | Ref / revision | Repository subdirectory |
| --- | --- | --- | --- |
''');
  pins.sort((a, b) => a.source.compareTo(b.source));
  for (final pin in pins) {
    out.writeln(
      '| ${_code(pin.source)} | ${_code(pin.url)} | ${_code(pin.ref)} '
      '| ${pin.path.isEmpty ? '—' : _code(pin.path)} |',
    );
  }
  return out.toString();
}

void _cargo(StringBuffer out, List<_GitPin> pins) {
  const roots = [
    'packages/onion/rust/Cargo.toml',
    'packages/rust_bindings/rust/Cargo.toml',
  ];
  final manifests = SplayTreeMap<String, _Manifest>();
  void read(String path) {
    if (manifests.containsKey(path)) return;
    final manifest = TomlDocument.parse(File(path).readAsStringSync()).toMap();
    manifests[path] = manifest;
    for (final (_, deps) in _cargoGroups(manifest)) {
      for (final dep in _dependencies(deps, _cargoScopes)) {
        if (dep.spec case {'path': final String localPath}) {
          read(
            p.posix.normalize(
              p.posix.join(p.posix.dirname(path), localPath, 'Cargo.toml'),
            ),
          );
        }
      }
    }
  }

  roots.forEach(read);
  out.write('''

## Rust: manifest → direct crates

Local path crates are shown and their own manifests are inventoried separately. Runtime includes optional declarations; target-specific declarations name their target.

| Manifest | Crate | Scope | Constraint / source |
| --- | --- | --- | --- |
''');
  for (final MapEntry(key: path, value: manifest) in manifests.entries) {
    final owner = _map(manifest['package'])['name'] as String;
    for (final (target, group) in _cargoGroups(manifest)) {
      for (final dep in _dependencies(group, _cargoScopes)) {
        final scope = target.isEmpty ? dep.scope : '${dep.scope} ($target)';
        final spec = dep.spec;
        final _Manifest options = spec is Map ? _map(spec) : const {};
        final name = options['package'];
        final constraint = [
          if (spec is String) spec,
          if (options['version'] case final String version) version,
          if (options['path'] case final String path) 'path: $path',
          if (options.containsKey('git')) 'git (see below)',
          if (options['registry'] case final String registry)
            'registry: $registry',
          if (options['workspace'] == true) 'workspace',
          if (options['optional'] == true) 'optional',
        ];
        out.writeln(
          '| [${_code(owner)}]($path) | ${_code(dep.name)}'
          '${name == null || name == dep.name ? '' : ' (${_code(name)})'} '
          '| ${_code(scope)} | ${_list(constraint.map(_code))} |',
        );
        _cargoPin(pins, '$owner / ${dep.name} ($scope)', options);
      }
    }
    for (final MapEntry(key: registry, value: patches) in _map(
      manifest['patch'],
    ).entries) {
      for (final MapEntry(key: name, value: spec) in _map(patches).entries) {
        if (spec is Map) {
          _cargoPin(pins, '$owner / $name (patch $registry)', _map(spec));
        }
      }
    }
  }
}

Iterable<(String, _Manifest)> _cargoGroups(_Manifest manifest) sync* {
  yield ('', manifest);
  final targets = _map(manifest['target']);
  for (final target in targets.keys.toList()..sort()) {
    yield (target, _map(targets[target]));
  }
}

void _cargoPin(List<_GitPin> pins, String source, _Manifest options) {
  if (options['git'] case final String url) {
    pins.add((
      source: 'Rust: $source',
      url: url,
      ref: switch (options) {
        {'rev': final String rev} => rev,
        {'tag': final String tag} => 'tag: $tag',
        {'branch': final String branch} => 'branch: $branch',
        _ => 'not pinned',
      },
      path: '',
    ));
  }
}

String _pubCell(_Dependency dep) {
  final constraint = switch (dep.spec) {
    {'sdk': final String sdk} => 'SDK: $sdk',
    {'git': _} => 'git (see below)',
    {'path': final String path} => 'path: $path',
    final Map spec => '${spec['version'] ?? 'any'}',
    final String version => version,
    _ => 'any',
  };
  return '${_code(dep.name)} (${_code(constraint)})';
}

Iterable<_Dependency> _byScope(Iterable<_Dependency> deps, String scope) =>
    deps.where((dep) => dep.scope == scope);

String _link(_Member member) =>
    '[${_code(member.name)}](${p.posix.join(member.path, 'pubspec.yaml')})';

String _list(Iterable<String> entries) =>
    entries.isEmpty ? '—' : entries.join(', ');

String _code(Object value) => '`${'$value'.replaceAll('|', r'\|')}`';
